(()=>{function j(){for(let f of document.querySelectorAll(".course-card"))f.addEventListener("click",(m)=>{if(m.target?.closest("a, button"))return;if(window.getSelection()?.toString().length)return;let h=f.querySelector(".cours-card-link-block");if(h)window.location.href=h.href})}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",j);else j();})();
